import json
import math
import re
from pathlib import Path

STOP = {
    "a", "an", "the", "is", "are", "of", "to", "in", "on", "for", "and", "or",
    "how", "what", "when", "where", "who", "which", "must", "may", "do", "does",
    "be", "by", "with", "it", "at", "as", "can", "i", "my", "much", "many",
}


def tokens(text):
    return [t for t in re.findall(r"[a-z0-9]+", text.lower()) if len(t) > 1 and t not in STOP]


def sentences(text):
    return [s.strip() for s in re.split(r"(?<=[.!?])\s+", text) if s.strip()]


class BM25:
    """Okapi BM25 over a list of passages."""

    def __init__(self, passages, k1=1.2, b=0.75):
        self.passages = passages
        self.toks = [tokens(p) for p in passages]
        self.k1, self.b = k1, b
        self.avg = sum(len(t) for t in self.toks) / max(1, len(self.toks))
        self.df = {}
        for toks in self.toks:
            for tok in set(toks):
                self.df[tok] = self.df.get(tok, 0) + 1

    def score(self, query, i):
        n = len(self.toks)
        toks = self.toks[i]
        total = 0.0
        for term in set(tokens(query)):
            tf = toks.count(term)
            if not tf:
                continue
            idf = math.log(1 + (n - self.df[term] + 0.5) / (self.df[term] + 0.5))
            norm = self.k1 * (1 - self.b + self.b * len(toks) / self.avg)
            total += idf * tf * (self.k1 + 1) / (tf + norm)
        return total

    def top(self, query, k):
        order = sorted(range(len(self.passages)), key=lambda i: -self.score(query, i))
        return [self.passages[i] for i in order[:k]]


data = json.loads(Path(__file__).with_name("input.json").read_text())


def answer(rows):
    print(json.dumps({"results": rows}))


# The words people ask with, mapped to the words the guide answers with.
ASKED_AS = {"notice": ["advance", "working", "days"], "often": ["times"], "monthly": ["month"], "late": ["before", "hours"]}

paragraphs = [p.strip() for doc in data["corpus"] for p in doc["text"].split("\n\n") if p.strip()]
index = BM25(paragraphs)


def best_fact(question, paragraph):
    asked = set(tokens(question))
    for word in list(asked):
        asked.update(ASKED_AS.get(word, []))
    lead, *facts = sentences(paragraph)
    # The lead names the service; the fact being asked about shares the
    # question's other words.
    return max(facts, key=lambda fact: len(asked & set(tokens(fact))))


rows = []
for q in data["questions"]:
    best = index.top(q["question"], 3)
    rows.append({"id": q["id"], "passages": [best_fact(q["question"], p) for p in best]})
answer(rows)
